return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-06 01:48+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=3; plural=(n==1) ? 0 : (n>=2 && n<=4) ? 1 : 2;','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Prejsť na Vyhľadávanie zásuvných modulov','Activate %s' => 'Aktivovať %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> vyžaduje, aby bol nainštalovaný a aktivovaný <strong>%2$s</strong>. <a href="%4$s">%3$s</a>','Enter your code here' => 'Zadajte svoj kód tu','Add %s' => 'Pridať %s','Remove' => 'Odstránenie stránky','Order number and receipt will be sent to this email address.' => 'Na túto e-mailovú adresu vám bude zaslané číslo objednávky a potvrdenie o jej prijatí.','Apartment, unit, building, floor, etc.' => 'Byt, jednotka, budova, poschodie atď.','Shipping phone' => 'Prepravný telefón','Only used for shipping-related questions.' => 'Používa sa len na otázky týkajúce sa prepravy.','Single step' => 'Jeden krok','Click to go to the order summary' => 'Kliknutím prejdete na súhrn objednávky','Cart total:' => 'Celkový počet košíkov:','Proceed to %s' => 'Pokračujte na %s','Proceed to contact' => 'Pokračujte v kontaktovaní','Proceed to shipping' => 'Prejsť na odoslanie','Proceed to billing' => 'Prejsť na fakturáciu','Proceed to payment' => 'Prejsť na platbu','Shipping method' => 'Spôsob prepravy','Additional notes' => 'Ďalšie poznámky','Payment method' => 'Spôsob platby','Step %1$s of %2$s' => 'Krok %1$s z %2$s','Change: %s' => 'Zmena: %s','Not selected yet.' => 'Zatiaľ nevybrané.','Same as shipping address' => 'Rovnaká ako dodacia adresa','Same as billing address' => 'Rovnaká ako fakturačná adresa','Order summary' => 'Zhrnutie objednávky','Edit cart' => 'Upraviť košík','Did you mean %s?' => 'Mysleli ste %s?','Change email address to: {suggestion-value}' => 'Zmeniť e-mailovú adresu na: {návrh-hodnota}','This is a required field.' => 'Toto pole je povinné.','This is not a valid email address.' => 'Toto nie je platná e-mailová adresa.','This field does not match the related field value.' => 'Toto pole sa nezhoduje s hodnotou súvisiaceho poľa.','The CPF number "{cpf_number}" is invalid.' => 'Číslo CPF "{cpf_number}" je neplatné.','The CNPJ number "{cnpj_number}" is invalid.' => 'Číslo CNPJ "{cnpj_number}" je neplatné.','(Required)' => '(povinné)','Checkout Header - Desktop' => 'Hlavička pokladnice - Pracovná plocha','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Zobrazenie widgetov v záhlaví pokladnice pre veľké obrazovky. Zobrazuje sa len v prípade, že používate záhlavie pokladnice zásuvného modulu.','Checkout Header - Mobile' => 'Hlavička pokladnice - mobilné zariadenia','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Zobrazenie widgetov pod hlavičkou pokladnice pre mobilné zariadenia. Zobrazuje sa len v prípade, že používate záhlavie pokladnice zásuvného modulu.','Checkout Sidebar' => 'Pokladňa Bočný panel','Display widgets on the checkout sidebar after the order summary.' => 'Zobrazenie widgetov na bočnom paneli pokladne za súhrnom objednávky.','Checkout Order Summary' => 'Zhrnutie objednávky pri pokladni','Display widgets inside the order summary at the checkout page.' => 'Zobrazenie widgetov v súhrne objednávky na stránke pokladnice.','Checkout Below Place Order' => 'Pokladňa Nižšie Umiestnite objednávku','Display widgets below the place order button at the checkout page.' => 'Zobrazenie widgetov pod tlačidlom odoslať objednávku na stránke pokladnice.','Checkout Footer' => 'Pätička pokladnice','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Zobrazenie widgetov v pätičke pokladnice. Zobrazuje sa len v prípade, že používate pätičku pokladnice doplnku.','Classic' => 'Klasické','Boxed' => 'Krabica','Split' => 'Split','Minimalist' => 'Minimalistický','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Pluginy Fluid Checkout a Delivery Date od CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Zistili sme, že používate pluginy Čas dodania a dátum vyzdvihnutia pre WooCommerce (zadarmo a PRO) od CodeRockz. Integrácia s týmito zásuvnými modulmi bola presunutá do Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Upgrade na PRO','Fluid Checkout database updated successfully' => 'Úspešná aktualizácia databázy Fluid Checkout','The database changes where applied successfully.' => 'Zmeny v databáze boli úspešne aplikované.','Dismiss' => 'Odmietnuť','Fluid Checkout database update' => 'Aktualizácia databázy Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'V databáze sú potrebné niektoré zmeny. Tak ako pri každej aktualizácii, odporúčame vám, aby ste si <strong>pred pokračovaním vykonali úplnú zálohu webovej stránky</strong>.','Update database' => 'Aktualizácia databázy','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout nie je kompatibilný s rozložením pokladní Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout potrebuje na fungovanie klasický pokladničný formulár založený na skratkách WooCommerce. Pri používaní nástroja Divi Builder na prispôsobenie vzhľadu stránky pokladnice sa klasické skratky nahradia vlastnými widgetmi z nástroja Divi Builder pre každú časť stránky pokladnice. Tieto vlastné widgety nie sú kompatibilné so systémom Fluid Checkout.</p><p>Prosím, upravte svoju stránku s pokladňou a nahraďte widgety Divi Builder textovým widgetom obsahujúcim skratku <code>[woocommerce_checkout]</code>.</p>','Edit the checkout page' => 'Úprava stránky pokladnice','Read the documentation.' => 'Prečítajte si dokumentáciu.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Germanizovaná funkcia viacstupňového pokladničného systému PRO musí byť pri používaní služby Fluid Checkout vypnutá','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Pri používaní Fluid Checkout sa funkcia viacerých krokov zo zásuvného modulu Germanized PRO stáva zbytočnou a môže spôsobiť <strong>kritické chyby pri spracovaní nových objednávok</strong>. V nastaveniach zásuvného modulu Germanized PRO vypnite funkciu viackrokového pokladničného systému.','Go to Germanized settings' => 'Prejsť na germanizované nastavenia','Thanks for choosing Fluid Checkout!' => 'Ďakujeme, že ste si vybrali službu Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Zásuvný modul používate už nejaký čas. Ako sa vám zatiaľ páči? <br>Prosím, dajte nám krátke hodnotenie, vážime si každú spätnú väzbu a povzbudzuje nás to k ďalšiemu zlepšovaniu pluginu :)','Rate the plugin' => 'Hodnotenie zásuvného modulu','I need help!' => 'Potrebujem pomoc!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Niektoré funkcie WooCommerce Checkout Manager by Quadlayers nemusia fungovať podľa očakávania, keď ich používate s Fluid Checkout. Prečítajte si <a href="%s">našu dokumentáciu</a> pre viac informácií a alternatívne riešenia.','Read documentation' => 'Prečítajte si dokumentáciu','Don\'t show this again' => 'Už to neukazujte','Fluid Checkout PRO' => 'Kontrola tekutín PRO','More design templates' => 'Ďalšie šablóny dizajnu','Optimized cart page' => 'Optimalizovaná stránka košíka','Optimized order received / thank you page' => 'Optimalizovaná stránka prijatej objednávky / poďakovania','Edit cart contents at checkout page' => 'Úprava obsahu košíka na stránke pokladnice','Account matching / user matching' => 'Párovanie účtov / párovanie používateľov','Trust symbols on the cart and thank you pages' => 'Symboly dôvery na stránkach košíka a poďakovania','More positions for the coupon code on the checkout page' => 'Viac pozícií pre kód kupónu na stránke pokladnice','International phone numbers' => 'Medzinárodné telefónne čísla','Gift messages and packing slips' => 'Darčekové správy a baliace lístky','Local pickup and in-store collection' => 'Miestny odber a vyzdvihnutie v predajni','EU-VAT Assistant' => 'Asistent pre DPH v EÚ','I already have it – Hide this offer' => 'Už ho mám - Skryť túto ponuku','Activated' => 'Aktivované','Address book' => 'Adresár','Select an image' => 'Vyberte obrázok','Cart layout' => 'Rozloženie košíka','Cart optimizations' => 'Optimalizácie košíka','Enable cart page optimizations' => 'Povolenie optimalizácie stránky košíka','Header and footer template' => 'Šablóna záhlavia a päty','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Ovláda, či sa má použiť záhlavie a päta stránky bez rozptyľovania alebo či sa má zachovať záhlavie a päta aktuálne aktívnej témy.','Distraction free header and footer' => 'Záhlavie a päta bez rozptyľovania','Theme\'s header and footer' => 'Záhlavie a päta témy','Cart elements' => 'Prvky košíka','Make the order summary stay visible on the cart page while scrolling' => 'Zabezpečte, aby zhrnutie objednávky zostalo viditeľné na stránke košíka počas posúvania','Coupon codes' => 'Kódy kupónov','Hidden' => 'Skryté','Before the cart items section' => 'Pred sekciou položiek košíka','Inside the cart items section' => 'Vnútri sekcie položiek košíka','After the cart items section' => 'Po sekcii položiek košíka','Before the shipping section' => 'Pred sekciou prepravy','After the shipping section' => 'Po sekcii prepravy','Before the order summary' => 'Pred zhrnutím objednávky','Inside the order summary' => 'Vnútri súhrnu objednávky','Before the order totals' => 'Pred súčtom objednávok','After the order totals' => 'Po súčtoch objednávok','After the order summary' => 'Po zhrnutí objednávky','Shipping' => 'Preprava','Select position where to display the shipping costs and calculator on the cart page.' => 'Vyberte miesto, kde sa majú na stránke košíka zobrazovať náklady na dopravu a kalkulačka.','Display as a cart section' => 'Zobrazenie ako časť vozíka','Cross-sells' => 'Krížové predaje','Select position where to display the cross-sells section on the cart page.' => 'Vyberte pozíciu, kde sa má na stránke košíka zobraziť sekcia krížových predajov.','Before the cart actions' => 'Pred akciami vozíka','After the cart actions' => 'Po akciách s vozíkom','Layout of cross-sell items on the cart page.' => 'Rozloženie položiek krížového predaja na stránke košíka.','Optimized horizontal cross-sells layout' => 'Optimalizované horizontálne rozloženie krížových predajov','Theme\'s cross-sells layout' => 'Rozloženie krížových predajov témy','Number of cross-sell items to display on the cart page' => 'Počet položiek krížového predaja, ktoré sa majú zobraziť na stránke košíka','Add widget areas to the cart page' => 'Pridanie oblastí widgetov na stránku košíka','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Tieto oblasti widgetov sa používajú na pridanie symbolov dôveryhodnosti a odznakov dôveryhodnosti na stránku košíka.','Checkout' => 'Pokladňa','Checkout layout' => 'Rozloženie pokladnice','Design template' => 'Šablóna dizajnu','Dark mode' => 'Tmavý režim','Enable dark mode' => 'Povolenie tmavého režimu','Logo image' => 'Obrázok loga','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Vyberte si obrázok, ktorý sa má zobraziť v záhlaví stránky s pokladňou. Platí len pri použití záhlavia a päty bez rozptyľovania.','Header background color' => 'Farba pozadia hlavičky','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Vyberte farbu pozadia pre záhlavie stránky s pokladňou. Platí len pri použití záhlavia a päty bez rozptyľovania.','HTML color value. ie: #f3f3f3' => 'Hodnota farby HTML. t. j: #f3f3f3','Page background color' => 'Farba pozadia stránky','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Vyberte farbu pozadia na stránke pokladnice. Farba sa použije na prvok <em>body</em>.','Footer background color' => 'Farba pozadia päty','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Vyberte si farbu pozadia pre pätu pokladničnej stránky. Platí len pri použití záhlavia a päty bez rozptyľovania.','Progress bar' => 'Lišta priebehu','Display the checkout progress bar when using multi-step checkout layout' => 'Zobrazenie lišty postupu pri pokladni pri použití viackrokového rozloženia pokladne','Make the checkout progress bar stay visible while scrolling' => 'Zabezpečte, aby lišta postupu pri pokladni zostala viditeľná aj počas posúvania','Express checkout' => 'Expresné odhlásenie','Enable the express checkout section' => 'Povolenie sekcie expresného odhlásenia','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Zobrazí sekciu expresného odhlásenia pri pokladni, ak majú podporované platobné brány túto funkciu povolenú.','Display express checkout buttons in one line for larger screens' => 'Zobrazenie tlačidiel expresnej registrácie v jednom riadku pre väčšie obrazovky','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Ignorovanie ďalších povinných polí pri platbe pomocou kompatibilnej platobnej brány Express Checkout','Make the order summary stay visible while scrolling' => 'Zabezpečte, aby súhrn objednávky zostal viditeľný aj počas posúvania','Choose a background color for the order summary section.' => 'Vyberte farbu pozadia pre časť súhrnu objednávky.','Highlight the order totals row in the order summary table' => 'Zvýraznite riadok súčtov objednávok v tabuľke súhrnu objednávok','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Najužitočnejšie, keď časť súhrnu objednávky nemá zvýraznenú farbu pozadia. Môže sa použiť aj na stránkach Košík, Prijatá objednávka a Zobraziť objednávku pri použití služby Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Odkaz na akciu v súhrne objednávky pri pokladni.','Edit cart link' => 'Upraviť odkaz na košík','Cart items count' => 'Počet položiek v košíku','Link to shop page' => 'Odkaz na stránku obchodu','Cart items' => 'Položky košíka','Hide cart items errors at the checkout page' => 'Skryť chyby položiek košíka na stránke pokladnice','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Nezobrazujte správu o chybách položiek košíka v hornej časti stránky s pokladňou. Pri odoslaní pokladničného formulára na dokončenie nákupu sa tieto chybové hlásenia zobrazia vždy.','Place order' => 'Umiestnite objednávku','Define the position to display "Place order" and terms checkbox section.' => 'Definujte pozíciu na zobrazenie sekcie "Umiestniť objednávku" a zaškrtávacieho políčka s podmienkami.','Some options might not be compatible with some plugins and themes.' => 'Niektoré možnosti nemusia byť kompatibilné s niektorými pluginmi a témami.','Below the payment section' => 'Pod platobnou sekciou','Below the order summary' => 'Pod súhrnom objednávky','Both below the payment section and the order summary' => 'Pod platobnou časťou aj pod súhrnom objednávky','Add widget areas to the checkout page' => 'Pridanie oblastí widgetov na stránku pokladnice','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Tieto oblasti widgetov sa používajú na pridanie symbolov dôveryhodnosti a odznakov dôveryhodnosti na stránku s pokladňou.','Display the coupon codes section title' => 'Zobrazenie názvu sekcie kódov kupónov','Select position where to display the coupon codes section on the checkout page.' => 'Vyberte pozíciu, kde sa má zobrazovať časť s kódmi kupónov na stránke pokladnice.','Before the checkout steps' => 'Pred krokmi pri pokladni','As a substep before payment methods' => 'Ako čiastkový krok pred platobnými metódami','As a substep after payment methods' => 'Ako čiastkový krok po platobných metódach','Default button style' => 'Predvolený štýl tlačidla','"Add" link button' => 'Tlačidlo odkazu "Pridať"','Checkout fields' => 'Pokladničné polia','Optional fields' => 'Nepovinné polia','Hide optional fields behind a link button' => 'Skrytie voliteľných polí za tlačidlom odkazu','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Odporúčame ponechať túto možnosť zaškrtnutú, aby sa znížil počet otvorených vstupných polí, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">prečítať si výskum</a>.','Do not hide "Address line 2" fields behind a link button' => 'Neskrývajte polia "Riadok adresy 2" za tlačidlom odkazu','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Odporúča sa len vtedy, keď väčšina zákazníkov skutočne potrebuje pole "Riadok adresy 2", alebo keď je rozhodujúce získať správnu dodaciu adresu (napr. pri doručovaní potravín a iných výrobkov podliehajúcich skaze).','Billing address' => 'Fakturačná adresa','Select position where to display the billing address section on the checkout page.' => 'Vyberte pozíciu, kde sa má na stránke pokladnice zobrazovať časť s fakturačnou adresou.','As a step before shipping' => 'Ako krok pred odoslaním','As a sub-step before the shipping address section' => 'Ako čiastkový krok pred sekciou s dodacou adresou','As a sub-step after the shipping address section' => 'Ako čiastkový krok po sekcii dodacej adresy','As a step after shipping' => 'Ako krok po odoslaní','As a sub-step before the payment section' => 'Ako čiastkový krok pred platobnou časťou','Force billing and shipping addresses to the same (single section)' => 'Vynútiť rovnaké fakturačné a dodacie adresy (jedna sekcia)','Checkbox for "Same as shipping/billing address" checked by default' => 'Začiarkavacie políčko "Rovnaká ako dodacia/fakturačná adresa" je predvolene začiarknuté','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Zaškrtávacie políčko "Rovnaká ako odosielacia adresa" sa začne predvolene zaškrtávať, keď sa ako prvá zobrazí časť s odosielacou adresou. <br>Zaškrtávacie políčko "Rovnaká ako fakturačná adresa" sa začne štandardne zaškrtávať, keď sa ako prvá zobrazí časť s fakturačnou adresou. <br> Odporúčame ponechať túto možnosť začiarknutú, pretože sa tým výrazne zníži počet otvorených vstupných polí pri pokladni, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">prečítať si výskum</a>.','Highlight the billing address section in the checkout form' => 'Zvýraznite časť s fakturačnou adresou vo formulári na pokladni','Shipping address' => 'Dodacia adresa','Highlight the shipping address section in the checkout form' => 'Zvýraznite časť s dodacou adresou vo formulári pri pokladni','Shipping methods' => 'Spôsoby prepravy','Choose in which position to display the shipping methods section.' => 'Vyberte, v ktorej polohe sa má zobraziť časť s metódami prepravy.','Before shipping address' => 'Pred dodacou adresou','After shipping address' => 'Po dodacej adrese','Local pickup' => 'Miestne vyzdvihnutie','Removes shipping address section when a local pickup shipping method is selected.' => 'Odstráni časť s dodacou adresou, keď je vybraný spôsob dopravy s miestnym vyzdvihnutím.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Nahradí dodaciu adresu miestom vyzdvihnutia, ak je vybraný spôsob dopravy miestnym vyzdvihnutím.','Choose which address to save as the shipping address for local pickup orders.' => 'Vyberte, ktorú adresu chcete uložiť ako dodaciu adresu pre objednávky miestneho vyzdvihnutia.','Save the selected pickup location' => 'Uloženie vybraného miesta vyzdvihnutia','Save same as the billing address' => 'Uložiť rovnakú ako fakturačnú adresu','Do not save any shipping address' => 'Neukladajte žiadnu dodaciu adresu','Company name field for shipping address' => 'Pole s názvom spoločnosti pre dodaciu adresu','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Zmena viditeľnosti poľa s názvom spoločnosti v časti s dodacou adresou vo formulári objednávky.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Ak je pole nastavené ako "voliteľné", čo je predvolený stav viditeľnosti, nebudú aplikované žiadne zmeny, aby ostatné zásuvné moduly mohli aplikovať všetky zmeny, ktoré potrebujú.','Hidden (remove field)' => 'Skryté (odstrániť pole)','Optional' => 'Voliteľné','Required' => 'Požadované','Add shipping phone field to the checkout form.' => 'Pridanie poľa pre prepravný telefón do formulára objednávky.','Choose in which step to display the shipping phone field.' => 'Vyberte, v ktorom kroku sa má zobraziť pole prepravného telefónu.','Contact step' => 'Kontaktný krok','Billing phone' => 'Fakturačný telefón','Add billing phone field to the checkout form.' => 'Pridanie poľa fakturačného telefónu do formulára pokladnice.','Choose in which step to display the billing phone field.' => 'Vyberte, v ktorom kroku sa má zobraziť pole fakturačného telefónu.','Show country code beside the flag' => 'Zobrazenie kódu krajiny vedľa vlajky','Show an example of a valid phone number inside phone fields' => 'Zobrazenie príkladu platného telefónneho čísla vo vnútri polí telefónu','Do not change placeholders' => 'Nemeňte zástupné symboly','Show if not defined' => 'Zobraziť, ak nie je definované','Always show' => 'Vždy ukazujte','Order notes' => 'Poznámky k objednávke','Define the visibility of the additional order notes field.' => 'Definujte viditeľnosť poľa dodatočných poznámok k objednávke.','Gift options' => 'Možnosti darčekov','Allow customers to add a gift message and other gift related options to the order.' => 'Umožnite zákazníkom pridať k objednávke darčekovú správu a ďalšie možnosti súvisiace s darčekom.','Display the gift message as part of the order details table instead of a separate section' => 'Zobrazenie správy o darčeku ako súčasť tabuľky s podrobnosťami o objednávke namiesto samostatnej časti','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Táto možnosť ovplyvňuje stránku s potvrdením objednávky (ďakovnú stránku) a údaje o objednávke na stránkach účtu, e-mailov a baliacich lístkov.','Account matching' => 'Zhodnosť účtov','Enable the account matching feature' => 'Povolenie funkcie párovania účtov','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Priradiť objednávky hosťujúceho zákazníka k jeho existujúcemu účtu, ak už existuje účet s kontaktnými údajmi zákazníka.','Display message when an account exists with the email address provided' => 'Zobrazenie správy, keď existuje konto so zadanou e-mailovou adresou','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Nahradí polia na vytvorenie účtu oznámením a možnosťou prihlásiť sa. V niektorých kontextoch sa môže odporúčať ponechať túto možnosť vypnutú z dôvodu ochrany súkromia zákazníkov.','Dashboard' => 'Prístrojová doska','Integrations' => 'Integrácie','License keys' => 'Licenčné kľúče','Visit our website for more information about our plugins and add-ons.' => 'Navštívte našu webovú stránku, kde nájdete ďalšie informácie o našich doplnkoch a doplnkoch.','Order pay page' => 'Stránka s platbou objednávky','Order pay' => 'Objednávka platby','Enable order pay page optimizations' => 'Povolenie optimalizácie stránky s platbou objednávky','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Zmena rozloženia stránky s platbou objednávky pre existujúce objednávky, ktoré čakajú na platbu od zákazníka.','Add widget areas to the order pay page' => 'Pridanie oblastí widgetov na stránku s platbou objednávky','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Tieto oblasti widgetov sa používajú na pridanie symbolov dôveryhodnosti a odznakov dôveryhodnosti na stránku s platbou objednávky.','Thank you page & order details layout' => 'Rozloženie stránky s poďakovaním a podrobnosťami o objednávke','Order details optimizations' => 'Optimalizácia detailov objednávky','Enable thank you page and order details optimizations' => 'Povolenie optimalizácie stránky s poďakovaním a detailov objednávky','Changes the layout of order details on the thank you page and account pages.' => 'Zmena rozloženia údajov o objednávke na stránke s poďakovaním a na stránkach účtu.','Enable order details customizations on email notifications' => 'Povolenie prispôsobenia podrobností objednávky v e-mailových oznámeniach','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Zobrazenie nových sekcií a zmena poradia sekcií v e-mailových oznámeniach. Štýly detailov objednávky v e-mailových oznámeniach zostávajú nezmenené.','Thank you page' => 'Stránka s poďakovaním','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Tieto možnosti ovplyvňujú stránku s poďakovaním, známu aj ako stránka prijatej objednávky alebo stránka s potvrdením objednávky.','Order details layout' => 'Rozloženie podrobností objednávky','Display the order details with wide layout on the thank you page' => 'Zobrazenie podrobností o objednávke so širokým rozložením na stránke s poďakovaním','Add widget areas to the thank you page' => 'Pridanie oblastí widgetov na stránku s poďakovaním','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Tieto oblasti widgetov sa používajú na pridanie symbolov dôveryhodnosti a odznakov dôveryhodnosti na stránku s poďakovaním.','Order actions' => 'Objednávkové akcie','Choose in which position to display the order actions.' => 'Vyberte, v ktorej polohe sa majú zobrazovať akcie objednávky.','Inside the order overview' => 'Vnútri prehľadu objednávok','After the order overview' => 'Po prehľade objednávok','After order sections' => 'Po sekciách objednávky','Order status' => 'Stav objednávky','Display the order status progress bar' => 'Zobrazenie stavového riadku objednávky','Choose in which position to display the section.' => 'Vyberte, v ktorej polohe sa má sekcia zobraziť.','After the order overview and payment instructions' => 'Po prehľade objednávky a pokynoch na platbu','Before the order items section' => 'Pred sekciou položiek objednávky','Inside the order items section' => 'Vnútri sekcie položiek objednávky','After the order items section' => 'Za sekciou položiek objednávky','On the sidebar' => 'Na bočnom paneli','Order downloads' => 'Objednávky na stiahnutie','Gift message' => 'Darčeková správa','Tools' => 'Nástroje','Troubleshooting' => 'Riešenie problémov','Debug options' => 'Možnosti ladenia','Debug mode' => 'Režim ladenia','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Používanie režimu ladenia ovplyvňuje výkon webovej stránky. Túto možnosť používajte len pri riešení problémov.','Load unminified assets' => 'Načítanie neminimalizovaných aktív','Enhanced select fields' => 'Vylepšené výberové polia','Fix automatic zoom-in on form fields' => 'Oprava automatického priblíženia polí formulára','Set <code>font-size</code> inside form fields to 16px' => 'Nastavenie <code>font-size</code> vo vnútri polí formulára na 16px','Fluid Checkout' => 'Kontrola tekutín','Settings' => 'Nastavenia','Support' => 'Podpora','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Povýšte na PRO</a> a odomknite ďalšie možnosti.','(PRO)' => '(PRO)','(experimental)' => '(experimentálne)','Please verify your phone number.' => 'Overte si svoje telefónne číslo.','The Bluehost Plugin' => 'Plugin Bluehost','Custom fields' => 'Vlastné polia','Enable custom shipping email field' => 'Povolenie vlastného poštového e-mailového poľa','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Ak je táto funkcia povolená, do formulára pokladnice sa pridá pole s poštovým e-mailom zo zásuvného modulu Bluehost.','Captcha Pro by BestWebSoft' => 'Captcha Pro od BestWebSoft','Captcha position' => 'Pozícia Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Definujte pozíciu na zobrazenie časti captcha. Niektoré pozície nemusia fungovať v závislosti od zvoleného typu captcha.','Selecting a pickup point is required before proceeding.' => 'Pred pokračovaním je potrebné vybrať miesto vyzdvihnutia.','Pickup point' => 'Miesto vyzdvihnutia','Pickup point not selected yet.' => 'Miesto vyzdvihnutia ešte nebolo vybrané.','Pickup point:' => 'Miesto vyzdvihnutia:','Mailchimp for WooCommerce' => 'Mailchimp pre WooCommerce','Subscribe checkbox' => 'Zaškrtávacie políčko Prihlásiť sa','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Prepísať pozíciu zaškrtávacieho políčka na stránke objednávky a vždy ho zobraziť v kroku kontaktu','Before Shipping Address' => 'Pred odoslaním Adresa','(originally "%s")' => '(pôvodne "%s")','After Shipping Address' => 'Adresa po odoslaní','Selecting a collection point is required when shipping with FermoPoint.' => 'Pri preprave pomocou FermoPoint je potrebné vybrať zberné miesto.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Ak je začiarknuté, informuje používateľov o preklepoch v e-mailovej správe. (Táto funkcia bola vypnutá, pretože Fluid Checkout ponúka túto funkciu. Zmeny tejto možnosti sa neprejavia)','Enable Mail Check: (disabled feature)' => 'Povolenie kontroly pošty: (vypnutá funkcia)','Carrier:' => 'Prepravca:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce E-mail Marketing','Sign up checkbox position' => 'Pozícia začiarkavacieho políčka Registrácia','Move the sign up checkbox to the contact step' => 'Presunutie zaškrtávacieho políčka na registráciu do kroku kontaktu','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Ak je táto funkcia zapnutá, zaškrtávacie políčko sa presunie do kroku kontaktu nezávisle od miesta zobrazenia definovaného v nastaveniach doplnku Sendinblue.','Theme Betheme' => 'Téma Betheme','Checkout progress' => 'Pokrok pri pokladni','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Výstup sekcie krokov pri pokladni z Betheme na stránkach pokladne, košíka a prijatej objednávky.','Theme Fennik' => 'Téma Fennik','Breadcrumbs' => 'Drobky','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Výstup časti s omrvinkami z témy Fennik pri použití záhlavia a päty Fluid Checkout.','Theme Go' => 'Téma Go','My account layout' => 'Rozloženie môjho účtu','Enable wide layout on "My account" page.' => 'Povolenie širokého rozloženia na stránke "Môj účet".','Theme Impreza' => 'Téma Impreza','Header' => 'Záhlavie','Spacing for site header at the checkout page (in pixels)' => 'Rozstupy medzi záhlaviami stránok na stránke s pokladňou (v pixeloch)','Only applicable when using the Impreza theme header at the checkout page.' => 'Platí len pri použití záhlavia témy Impreza na stránke pokladnice.','Theme Kapee' => 'Téma Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Výstup sekcie krokov pri pokladni z témy Kapee na stránkach pokladne, košíka a prijatej objednávky.','Theme Porto' => 'Téma Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Výstup sekcie s krokmi pri pokladni z témy Porto na stránkach pokladne, košíka a prijatej objednávky.','Theme Pressmart' => 'Téma Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Výstup sekcie s krokmi pri pokladni z témy Pressmart na stránkach pokladne, košíka a prijatej objednávky.','Theme The Gem' => 'Téma drahokamu','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Výstup sekcie krokov pokladnice z témy Gem pri použití záhlavia a päty Fluid Checkout.','Theme Woodmart' => 'Téma Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Výstup sekcie krokov pokladnice z témy Woodmart pri použití záhlavia a päty Fluid Checkout.','Checkout options' => 'Možnosti odhlásenia','Disable the theme checkout options' => 'Zakázanie možností pokladnice témy','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Možnosti zobraziť obrázok produktu, pole množstva, tlačidlo odstrániť a odkaz na stránku produktu pridané témou sú predvolene vypnuté.','Theme Atomion' => 'Téma Atomion','Order progress' => 'Priebeh objednávky','Display order progress from the theme' => 'Zobrazenie priebehu objednávky z témy','Display the form field labels visible on the page' => 'Zobrazenie štítkov polí formulára viditeľných na stránke','It is recommended to keep this option enabled for a better user experience.' => 'Túto možnosť odporúčame ponechať zapnutú, aby sa používateľovi lepšie pracovalo.','Theme ZK Nito' => 'Téma ZK Nito','Add extra fields to the checkout form' => 'Pridanie ďalších polí do formulára na pokladni','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Pridá do sekcie s adresou na odoslanie ďalšie pole s e-mailom a telefónom na odoslanie.','Go to the home page' => 'Prejsť na domovskú stránku','Skip to content' => 'Prejsť na obsah','Create an account' => 'Vytvorenie konta','Log in to your account' => 'Prihláste sa do svojho konta','Already have an account?' => 'Už máte účet?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Prihlásený ako %1$s. <a href="%2$s">odhlásiť sa</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Vaša objednávka má celkovú dlžnú sumu %s. Nie je potrebná žiadna ďalšia platba.','Close and continue with checkout' => 'Zatvorte a pokračujte v pokladni','Continue' => 'Pokračovať','Parcel terminal' => 'Balíkový terminál','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Tento widget bol nahradený widgetom Fluid Checkout. </p><p>Pri používaní Fluid Checkout je potrebné, aby stránka s pokladňou používala pôvodný skrátený kód WooCommerce <code>[woocommerce_checkout]</code>, aby fungovala správne.</p><p>Pre viac informácií navštívte dokumentáciu Fluid Checkout.</p>','Theme The7' => 'Téma The7','Additional header sections' => 'Ďalšie sekcie záhlavia','Output additional header sections if enabled in the theme settings.' => 'Výstup ďalších sekcií záhlavia, ak je to povolené v nastaveniach témy.','More information' => 'Viac informácií','Pick a Locker' => 'Vyberte si skrinku','Page template' => 'Šablóna stránky','Use `Order confirmation` page template for block-based themes' => 'Použitie šablóny stránky `Potvrdenie objednávky` pre blokové témy','Only applies when using a block-based theme.' => 'Platí len pri použití témy založenej na blokoch.','WooCommerce Stripe Gateway' => 'Brána WooCommerce Stripe','Payment form' => 'Platobný formulár','Apply styles to the Stripe payment form fields' => 'Použitie štýlov na polia platobného formulára Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Ak je táto funkcia zapnutá, Fluid Checkout použije štýly optimalizované pre kompatibilitu s týmto doplnkom. Ak používate vlastné štýly pre polia platobného formulára Stripe, možno to budete chcieť vypnúť.','Theme Nyture' => 'Téma Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Výstup sekcie krokov pokladnice z témy Nyture pri použití Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Umožňuje zákazníkom uskutočniť platby za objednávky, ktoré boli vytvorené ručne správcom obchodu alebo neboli dokončené počas pokladnice.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Plugin WooCommerce Checkout Manager od Quadlayers nie je kompatibilný s Fluid Checkout','Company name field for billing address' => 'Pole s názvom spoločnosti pre fakturačnú adresu','Change visibility for the company name field for the billing address section on the checkout form.' => 'Zmena viditeľnosti poľa s názvom spoločnosti v časti s fakturačnou adresou vo formulári pokladnice.','Theme Bookshelf' => 'Téma Police na knihy','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Výstup sekcie krokov pri pokladni z témy Bookshelf pri použití Fluid Checkout.','Account password' => 'Heslo účtu','An account will be created with the information provided at checkout when completing the order.' => 'Účet bude vytvorený na základe informácií zadaných pri pokladni pri dokončovaní objednávky.','Choose the style of the progress bar.' => 'Vyberte štýl panela priebehu.','Bars' => 'Bary','Theme Ireca' => 'Téma Ireca','WooCommerce page layout' => 'Rozloženie stránky WooCommerce','Force wide layout on WooCommerce pages' => 'Vynútenie širokého rozloženia na stránkach WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Tým sa zabezpečí, že časť s obsahom nebude príliš úzka na stránkach WooCommerce vrátane stránok s pokladňou, košíkom, prijatou objednávkou, platbou objednávky a účtom.','WooCommerce Smart Coupons' => 'Inteligentné kupóny WooCommerce','Position on checkout page' => 'Pozícia na stránke pokladnice','Choose where to display the available coupons section on the checkout page.' => 'Vyberte, kde sa má na stránke pokladnice zobraziť časť s dostupnými kupónmi.','Before the progress bar' => 'Pred ukazovateľom priebehu','After the progress bar' => 'Po zobrazení ukazovateľa priebehu','Before coupon codes section' => 'Pred sekciou kódov kupónov','Format phone numbers according to the rules for each country.' => 'Formátujte telefónne čísla podľa pravidiel jednotlivých krajín.','Use precise phone number validation' => 'Používajte presné overovanie telefónnych čísel','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Ide o experimentálnu funkciu, ktorá nemusí vo všetkých nastaveniach fungovať podľa očakávania. Používajte ju opatrne.','Phone number validation types used when precise validation is enabled.' => 'Typy overovania telefónnych čísel, ktoré sa používajú, keď je povolené presné overovanie.','Mobile' => 'Mobilný portál','Fixed line' => 'Pevná linka','Toll free' => 'Bezplatné mýto','Or' => 'Alebo','Contact' => 'Kontakt','Multi step' => 'Viacnásobný krok','2 columns' => '2 stĺpce','1 column' => '1 stĺpec','Before checkout steps' => 'Kroky pred pokladňou','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Pri použití rozloženia pokladnice <em>"1 stĺpec"</em> je táto možnosť vždy nastavená na <em>"Pred krokmi pokladnice"</em> a platí aj pre zobrazenie na ploche.','Position for the extra order summary section on mobile.' => 'Pozícia pre dodatočnú sekciu súhrnu objednávky v mobilnom telefóne.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Možnosť <em>"V záhlaví stránky"</em> platí len pri použití záhlavia bez rozptyľovania.','On the site header (requires distraction-free header)' => 'V záhlaví stránky (vyžaduje záhlavie bez rozptyľujúcich prvkov)','Initial state for the expansible order summary section on mobile.' => 'Počiatočný stav pre rozširujúcu sa sekciu súhrnu objednávok v mobilnom telefóne.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Odporúčame ho nastaviť ako <em>rozšírený</em> pre nasledujúce krajiny kvôli regulačným požiadavkám: <strong>Nemecko</strong>, <strong>Rakúsko</strong>, <strong>Švajčiarsko</strong>, <strong>Holandsko</strong>, <strong>Poľsko</strong>, <strong>Belgicko</strong> a <strong>Francúzsko</strong>.','Collapsed' => 'Zrútené stránky','Expanded' => 'Rozšírené','Do not show' => 'Nezobrazujte','yes' => 'áno','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Pole pre telefónne číslo na doručenie môže byť označené ako „povinné“, ak sa sekcia fakturačnej adresy zobrazuje za sekciou doručovacej adresy a pole pre telefónne číslo na fakturáciu je nastavené ako „povinné“. Je to potrebné na to, aby sa doručovacia adresa mohla skopírovať do fakturačnej adresy, ak je táto možnosť zaškrtnutá; v opačnom prípade by zákazník nemusel byť schopný vyplniť formulár na dokončenie objednávky.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Pole pre telefónne číslo na fakturačné účely môže byť nastavené ako „povinné“, ak sa sekcia s fakturačnou adresou zobrazuje pred sekciou s dodacou adresou a pole pre telefónne číslo na dodanie je nastavené ako „povinné“. Je to potrebné na to, aby sa dodacie adresa mohla skopírovať do fakturačnej adresy, ak je táto možnosť zaškrtnutá; v opačnom prípade by zákazník nemusel byť schopný dokončiť formulár na dokončenie objednávky.','Settings profiles' => 'Profily nastavení','Settings profile' => 'Profil nastavení','You do not have permission to perform this action.' => 'Nemáte oprávnenie na vykonanie tejto akcie.','You do not have permission to activate plugins.' => 'Nemáte oprávnenie na aktiváciu doplnkov.','Missing plugin.' => 'Chýba doplnok.','Plugin activated.' => 'Plugin je aktivovaný.','The following changes will be applied:' => 'Budú uplatnené nasledujúce zmeny:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Od verzie Fluid Checkout 5.0 sa nastavenia ukladajú iným spôsobom. Staršie nastavenia sa naďalej uchovávajú v databáze, aby bolo v prípade potreby možné prejsť na predchádzajúce verzie.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Váš obchod beží s novými nastaveniami už približne 2 týždne, takže ste mohli odstrániť staré nastavenia uložené v databáze. Upozorňujeme, že ak po tomto vyčistení budete musieť prejsť na predchádzajúce verzie pluginu, ten bude pre všetky nastavenia používať predvolené hodnoty.','Fluid Checkout settings cleanup' => 'Vyčistenie nastavení funkcie „Fluid Checkout“','Delete leftover options' => 'Odstrániť nevyužité možnosti','Help us improve Fluid Checkout' => 'Pomôžte nám vylepšiť službu Fluid Checkout','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Zdieľajte anonymné správy o prostredí webových stránok prostredníctvom služby Fluid Checkout, aby ste získali rýchlejšiu podporu a pomohli nám zlepšiť kompatibilitu a zmerať dopad. Neobsahujú žiadne údaje o zákazníkoch, používateľoch ani citlivé údaje. V nastaveniach v časti Nástroje si môžete kedykoľvek vybrať, čo sa má zdieľať.','Enable site environment reports' => 'Aktivovať správy o prostredí webu','Review settings' => 'Nastavenia recenzií','This preview has expired. Reload the admin page to start a new preview.' => 'Platnosť tohto náhľadu vypršala. Na spustenie nového náhľadu obnovte stránku správcu.','Preview expired' => 'Platnosť náhľadu vypršala','Orders cannot be placed in the preview.' => 'V náhľade nie je možné zadávať objednávky.','Logging in is not available in the preview.' => 'V náhľade nie je k dispozícii možnosť prihlásenia.','Accounts cannot be created in the preview.' => 'V náhľade nie je možné vytvárať účty.','Requests to other sites are blocked in the preview.' => 'V náhľade sú blokované požiadavky na iné stránky.','Processing…' => 'Spracúva sa…','Something went wrong. Please try again.' => 'Niečo sa nepodarilo. Skúste to prosím znova.','Activate plugin' => 'Aktivovať doplnok','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO – Kompletný balík riešení pre platobný proces','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Všetky funkcie verzie PRO + všetky doplnky v jednej cene. Šablóny dizajnu, optimalizované stránky nákupného košíka a potvrdenia objednávky, synchronizácia účtov a mnoho ďalšieho.','Optimized order pay page' => 'Optimalizovaná stránka na platbu objednávky','Express checkout buttons from supported payment methods' => 'Tlačidlá rýchlej platby pre podporované platobné metódy','Delayed account creation' => 'Oneskorené vytvorenie účtu','Address autocomplete with Google Maps APIs' => 'Automatické dopĺňanie adries pomocou rozhraní API služby Google Maps','Multiple saved addresses with the address book' => 'Viac uložených adries v adresári','EU-VAT assistant' => 'Pomocník pre DPH v EÚ','Hide this section' => 'Skryť túto časť','Learn more' => 'Zistiť viac','Get early access' => 'Získajte predčasný prístup','Activate add-on' => 'Aktivovať doplnok','Get more out of your checkout journey' => 'Využite svoj nákupný proces na maximum','Test API key' => 'Otestovať kľúč API','Guided setup' => 'Nastavenie s pomocou sprievodcu','Options' => 'Možnosti','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Nastavte rozloženie a dizajn v sekcii <a href="%s">možnosti platby</a>.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Aktivujte možnosť platby bez registrácie a/alebo skontrolujte <a href="%s">nastavenia zákazníckych účtov</a>.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Aktivujte optimalizované stránky <a href="%1$s">košík</a>, <a href="%2$s">poďakovanie</a> a <a href="%3$s">platba za objednávku</a>.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Zapnite <a href="%s">automatické dopĺňanie adries</a> z Google Maps.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Aktivujte funkciu viacerých uložených adries pomocou <a href="%s">adresára</a>.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Skontrolujte, či sú pre danú šablónu alebo iné nainštalované pluginy k dispozícii nejaké <a href="%s">možnosti integrácie</a>.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Získajte rýchlejšiu podporu a pomôžte nám zlepšiť kompatibilitu a zmerať dosah. <a href="%s">Aktivujte sledovanie používania</a> v nastaveniach nástrojov.','Missing settings tab.' => 'Chýba záložka „Nastavenia“.','Getting started' => 'Ako začať','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Skvelé! Vaša stránka platby teraz beží na platforme Fluid Checkout.</strong> Tu je niekoľko krokov, ako začať:','Completed' => 'Dokončené','Preview report data' => 'Náhľad údajov v správe','Send now' => 'Odoslať teraz','Auto-detect' => 'Automatická detekcia','Afrikaans' => 'afrikánčina','Albanian' => 'albánčina','Amharic' => 'amharský jazyk','Arabic' => 'arabčina','Armenian' => 'arménčina','Azerbaijani' => 'Azerbajdžanský','Basque' => 'baskičtina','Belarusian' => 'bieloruský','Bengali' => 'bengálčina','Bosnian' => 'bosniansky','Bulgarian' => 'bulharčina','Burmese' => 'barmský','Catalan' => 'katalánčina','Chinese' => 'Čínština','Chinese (Simplified)' => 'Čínština (zjednodušená)','Chinese (Hong Kong)' => 'Čínština (Hongkong)','Chinese (Traditional)' => 'Čínština (tradičná)','Croatian' => 'chorvátsky','Czech' => 'Česky','Danish' => 'dánčina','Dutch' => 'holandčina','English' => 'angličtina','English (Australian)' => 'Angličtina (austrálska)','English (Great Britain)' => 'Angličtina (Veľká Británia)','Estonian' => 'estónčina','Farsi' => 'perzština','Finnish' => 'fínčina','Filipino' => 'filipínsky','French' => 'francúzština','French (Canadian)' => 'Francúzština (kanadská)','Galician' => 'galícijčina','Georgian' => 'gruzínčina','German' => 'nemčina','Greek' => 'gréčtina','Gujarati' => 'gudžarátsky','Hebrew' => 'hebrejčina','Hindi' => 'hindčina','Hungarian' => 'maďarčina','Icelandic' => 'islandský','Indonesian' => 'indonézsky','Italian' => 'taliančina','Japanese' => 'Japončina','Kannada' => 'Kannada','Kazakh' => 'kazašský','Khmer' => 'khmérčina','Korean' => 'kórejčina','Kyrgyz' => 'Kirgiz','Lao' => 'Laos','Latvian' => 'lotyšský','Lithuanian' => 'litovský','Macedonian' => 'Makedónčina','Malay' => 'malajčina','Malayalam' => 'malajalamčina','Marathi' => 'maráthčina','Mongolian' => 'mongolský','Nepali' => 'nepálčina','Norwegian' => 'nórčina','Polish' => 'Poľština','Portuguese' => 'portugalčina','Portuguese (Brazil)' => 'portugalčina (Brazília)','Portuguese (Portugal)' => 'portugalčina (Portugalsko)','Punjabi' => 'pandžábčina','Romanian' => 'rumunčina','Russian' => 'ruština','Serbian' => 'srbský','Sinhalese' => 'singálčina','Slovak' => 'slovak','Slovenian' => 'slovinčina','Spanish' => 'španielčina','Spanish (Latin America)' => 'Španielčina (Latinská Amerika)','Swahili' => 'svahilčina','Swedish' => 'Švédčina','Tamil' => 'Tamilčina','Telugu' => 'telugština','Thai' => 'Thajčina','Turkish' => 'turečtina','Ukrainian' => 'ukrajinčina','Urdu' => 'urdčina','Vietnamese' => 'vietnamčina','Zulu' => 'Zulu','Google address autocomplete' => 'Automatické dopĺňanie adries v Google','Google Places API version' => 'Verzia rozhrania API služby Google Places','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Vyberte si, ktorú verziu rozhrania API služby Google Places chcete používať. Odporúčame čo najskôr prejsť na nové rozhranie API služby Places.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Odporúčame používať „Places API (New)“, pretože od 1. marca 2025 spoločnosť Google prejde verziu „Places API (Legacy)“ do stavu Legacy, čo znamená, že túto službu už nebude možné aktivovať pre nové kľúče API a táto verzia API nakoniec prestane byť k dispozícii. Existujúce účty, ktoré už používajú staršiu verziu API, budú naďalej fungovať bez prerušenia.','(Recommended)' => '(Odporúčané)','Google API key' => 'Kľúč API služby Google','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Vložte svoj kľúč Google API a pomocou tlačidla „Test“ overte, či na tejto webovej stránke funguje. Uistite sa, že kľúč je platný a povolený pre vašu doménu, inak by mohlo dôjsť k zablokovaniu poľa na zadávanie adresy, čo by zákazníkom zabránilo v dokončení objednávok.','Enable Google address autocomplete' => 'Zapnúť automatické dopĺňanie adries od Google','Enable address autocompletion using the Google Maps APIs.' => 'Aktivujte automatické dopĺňanie adries pomocou rozhraní API služby Google Maps.','Google API language' => 'Jazyk rozhrania API služby Google','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Tento jazyk sa bude používať na zobrazovanie návrhov adries z rozhrania API služby Google Places a adresy sa budú v tomto jazyku aj automaticky dopĺňať.','Result types' => 'Typy výsledkov','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Nechajte pole prázdne, ak chcete akceptovať akýkoľvek typ výsledkov, čo zvyčajne vedie k lepším výsledkom vyhľadávania. <a href="%s" target="_blank">Ďalšie podrobnosti nájdete v dokumentácii</a>. <br>Vyberte až 5 typov výsledkov vyhľadávania adries, ktoré sa majú zobrazovať v poliach automatického dopĺňania adries. <br>Navštívte dokumentáciu Google Maps, kde sa dozviete viac o <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">podporovaných typoch</a>.','Result types (Legacy API)' => 'Typy výsledkov (staršie rozhranie API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Aký typ výsledkov vyhľadávania adries sa má vrátiť pri používaní rozhrania Places API (staršia verzia). <br>Navštívte dokumentáciu k staršej verzii rozhrania Google Places API, kde sa dozviete viac o <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">podporovaných typoch</a>.','Company fields' => 'Polia spoločnosti','Enable autocomplete for the company name if available' => 'Ak je to možné, zapnúť automatické dopĺňanie názvu spoločnosti','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Aktivujte automatické dopĺňanie poľa „spoločnosť“ údajmi o názve spoločnosti, ktoré sa získajú z rozhraní API služby Google Maps.','Business search' => 'Vyhľadávanie firiem','Enable search for businesses in the company field' => 'Povoliť vyhľadávanie firiem v poli „spoločnosť“','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Pri zadávaní textu do poľa „Spoločnosť“ aktivujte návrh adries spojených s danou firmou a po výbere firmy z návrhov automaticky vyplňte všetky polia týkajúce sa adries.','Company result types' => 'Typy výsledkov spoločnosti','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Vyberte až 5 typov výsledkov vyhľadávania adries, ktoré sa majú zobrazovať pri automatickom dopĺňaní polí týkajúcich sa spoločností. <br>Odporúčaná hodnota je <code>podnik</code>, ktorá zahŕňa väčšinu typov podnikov. <br>Ak pole ponecháte prázdne, budú akceptované akékoľvek typy výsledkov, vrátane tých, ktoré nesúvisia s podnikmi. <br>Navštívte dokumentáciu Google Maps, kde sa dozviete viac o <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">podporovaných typoch</a>.','Google logo' => 'Logo spoločnosti Google','Show text and logo "Powered by Google"' => 'Zobraziť text a logo „Powered by Google“','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Ak je táto možnosť zaškrtnutá, v spodnej časti poľa s návrhmi na automatické dopĺňanie adresy sa zobrazí text a logo „Powered by Google“.','Brasil API address autocomplete' => 'Automatické dopĺňanie adries v Brazílii prostredníctvom API','Brasil API' => 'API pre Brazíliu','Enable Brasil API address autocomplete for CEP fields' => 'Aktivovať automatické dopĺňanie adries prostredníctvom rozhrania API pre Brazíliu v poliach CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Pomocou rozhrania API Brasil môžete načítať a automaticky vyplniť adresy pomocou poľa CEP/PSČ. Platí len pre brazílske adresy.','API version' => 'Verzia API','Choose which version of the Brasil API CEP method to use.' => 'Vyberte, ktorú verziu metódy CEP rozhrania API Brasil chcete použiť.','Address book migration' => 'Prenos adresára','WooCommerce addresses' => 'Adresy WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Skopírujte existujúce dodacie a fakturačné adresy z WooCommerce do adresára zákazníkov.','Enable the address book feature' => 'Aktivovať funkciu adresára','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Umožnite zákazníkom uložiť viacero adries a nastaviť predvolenú adresu, ktorá sa bude používať na doručenie a fakturáciu.','Address labels' => 'Adresné štítky','Allow customers to add a custom label for each address' => 'Umožnite zákazníkom pridať vlastný názov pre každú adresu','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Adresné štítky uľahčujú zákazníkom rozlišovanie medzi ich uloženými adresami (napr.: „Dom u mamy“). Adresné štítky sú súkromné a nebudú sa zobrazovať ani tlačiť na stránke s podrobnosťami objednávky ani na faktúrach.','Display layout' => 'Rozloženie obrazovky','Choose how saved addresses are displayed at checkout and on the cart.' => 'Zvoľte si, ako sa majú uložené adresy zobrazovať pri platbe a v košíku.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Použije sa pri platbe a v košíku. Uložené adresy na stránke účtu sa vždy zobrazujú v rozložení kariet.','Address cards' => 'Vizitky','Address list' => 'Zoznam adries','Dropdown field' => 'Rozbaľovacie pole','Address search' => 'Vyhľadávanie adries','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Zobraziť filter vyhľadávania adries na používateľskom rozhraní, ak má zákazník k dispozícii aspoň tento počet uložených adries.','Not used when display layout is set to dropdown field.' => 'Nepoužíva sa, ak je rozloženie zobrazenia nastavené na roletové pole.','Addresses' => 'Adresy','Enable cart page optimizations to see more options' => 'Aktivujte optimalizácie stránky s košíkom, aby ste videli viac možností','Sticky order summary' => 'Zhrnutie objednávky (zachovať na vrchu stránky)','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Vyberte miesto, kde sa má na stránke košíka zobraziť sekcia s kupónovými kódmi. Platí len v prípade, že je povolený košík AJAX a ak je v nastaveniach WooCommerce povolené používanie kupónových kódov.','Layout of cross-sell' => 'Štruktúra krížového predaja','Cross-sells displayed' => 'Zobrazené doplnkové produkty','Items' => 'Položky','Cart page optimization' => 'Optimalizácia stránky s košíkom','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Zabezpečte, aby váš nákupný košík mal rovnaké prehľadné rozloženie zamerané na konverziu ako stránka platby.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Zosúlaďte rozloženie nákupného košíka so stránkou pokladne, aby bol nákupný proces jednotný.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Nákupný košík sa má na pozadí neustále aktualizovať, pri zmene množstiev sa nemá načítať celá stránka nanovo.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Umiestnite kódy zľavových kupónov, informácie o doručení a doplnkové ponuky presne tam, kde prinášajú najvyššiu konverziu.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Zabezpečte, aby bol prehľad objednávky viditeľný aj počas posúvania stránky, a pridajte symboly dôvery tam, kde zákazníci potrebujú uistenie.','Columns' => 'Stĺpce','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Všeobecné štýly pre jednotlivé kroky platby, prehľad objednávky a ďalšie sekcie. Platí pre ďalšie stránky: platba, košík, poďakovanie (objednávka prijatá) a zobrazenie objednávky.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Pri použití rozloženia <em>„1 stĺpec“</em> s dizajnovou šablónou <em>„Split“</em> sa pravý stĺpec zobrazí len vtedy, ak je aktívna oblasť widgetov v bočnom paneli stránky (bočný panel pokladne, bočný panel košíka alebo bočný panel prijatých objednávok). V opačnom prípade zostane stránka v jednostĺpcovom rozložení so štýlmi Split.','Split column background' => 'Rozdelené pozadie stĺpca','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Vyberte farbu pozadia pre sekundárny stĺpec v rozložení „Split“. Ak pole ponecháte prázdne, použije sa farba pozadia súhrnu objednávky.','Page templates' => 'Šablóny stránok','Checkout template' => 'Šablóna pokladne','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Odporúča sa na zníženie počtu rušivých faktorov pri dokončovaní nákupu. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Prečítajte si štúdiu o opúšťaní nákupného košíka</a>.','Sticky progress bar' => 'Lepiaci ukazovateľ priebehu','Progress bar style' => 'Štýl ukazovateľa priebehu','Order totals' => 'Celkové sumy objednávok','Background color' => 'Farba pozadia','Action link' => 'Akčný odkaz','Mobile order summary' => 'Prehľad mobilnej objednávky','Mobile initial state' => 'Počiatočný stav mobilného zariadenia','Enable editing cart items at checkout' => 'Povoliť úpravu položiek v košíku pri platbe','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Umožnite zákazníkom zmeniť množstvo produktov alebo odstrániť položky priamo na stránke pokladne.','Cart item errors' => 'Chyby v košíku','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Platí len vtedy, ak je kód kupónu zobrazený ako samostatná sekcia na stránkach pokladne alebo košíka a ak je v nastaveniach WooCommerce povolené používanie kódov kupónov.','Coupon codes position' => 'Umiestnenie kupónových kódov','Apply coupon button' => 'Tlačidlo „Použiť kupón“','Select style of the "apply coupon" button.' => 'Vyberte štýl tlačidla „Použiť kupón“.','Address line 2' => 'Adresný riadok 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Toto nastavenie platí pre sekcie „Pokladňa“ aj „Osobný odber“. V sekcii „Osobný odber“ tiež určuje, či sa voľba „Doručenie/Osobný odber“ zobrazí v rámci sekcie spôsobov doručenia (pred adresou) alebo ako samostatná sekcia (za ňou).','Customer accounts' => 'Zákaznícke účty','Guest checkout' => 'Pokladňa pre hostí','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Možnosti platby ako hosť, prihlásenia a vytvorenia účtu na stránke nastavení „Účty“ v WooCommerce. Pre vaše pohodlie sa spravujú práve tu, vďaka čomu môžete pre každý profil nastavení použiť odlišné hodnoty.','Allow customers to checkout without an account' => 'Umožnite zákazníkom dokončiť nákup bez vytvorenia účtu','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Odporúča sa</strong>, aby sa od zákazníkov pri dokončovaní objednávky nevyžadovalo vytvorenie účtu ani prihlásenie, čo môže znížiť mieru konverzie.','When disabled, customers must log in or create an account to complete the purchase.' => 'Ak je táto funkcia deaktivovaná, zákazníci sa musia prihlásiť alebo si vytvoriť účet, aby mohli dokončiť nákup.','Login at checkout' => 'Prihláste sa pri platbe','Enable log-in during checkout' => 'Povoliť prihlásenie počas dokončovania objednávky','Show a link for returning customers to log in from the checkout page.' => 'Na stránke pokladne zobrazte odkaz, cez ktorý sa môžu stály zákazníci prihlásiť.','Account creation' => 'Vytvorenie účtu','Allow customers to create an account during checkout' => 'Umožnite zákazníkom vytvoriť si účet počas dokončovania objednávky','Customers can create an account before placing their order.' => 'Zákazníci si môžu pred zadávaním objednávky vytvoriť účet.','Allow customers to create an account from the My account page' => 'Umožnite zákazníkom vytvoriť si účet na stránke „Môj účet“','Customers can register a new account from the My account page.' => 'Zákazníci si môžu vytvoriť nový účet na stránke „Môj účet“.','Username' => 'Používateľské meno','Generate from customer\'s name' => 'Vygenerovať na základe mena zákazníka','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Odporúča sa</strong>, aby sa od zákazníkov pri dokončovaní objednávky nevyžadovalo zadanie používateľského mena, čo môže znížiť mieru konverzie.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Používateľské meno sa generuje na základe mena zákazníka alebo, ak nie je možné použiť meno, na základe e-mailovej adresy.','Password' => 'Heslo','Send password setup link' => 'Odoslať odkaz na nastavenie hesla','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Odporúča sa</strong>, aby sa od zákazníkov pri dokončovaní objednávky nevyžadovalo zadanie hesla, čo môže znížiť mieru konverzie.','Customers receive an email to create their password securely.' => 'Zákazníci dostanú e-mail, v ktorom si môžu bezpečne vytvoriť heslo.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Umožnite registrovaným zákazníkom dokončiť nákup bez prihlásenia a priradiť objednávku k ich existujúcemu účtu, ak sa zhodujú kontaktné údaje.','Existing account message' => 'Správa týkajúca sa existujúceho účtu','Let customers create an account after placing their order, from the thank you page.' => 'Umožnite zákazníkom vytvoriť si účet po zadaniu objednávky priamo na stránke s poďakovaním.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Možnosti v tejto časti sú k dispozícii, ak sú povolené platby ako hosť a priradenie účtu. Ak chcete nakonfigurovať odložené vytvorenie účtu, povolte obe uvedené funkcie.','Enable delayed account creation' => 'Povoliť odložené vytvorenie účtu','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Povoliť odložené vytvorenie účtu, ak sú povolené ako platba bez registrácie, tak aj priradenie účtu.','Section position' => 'Poloha sekcie','Before customer details section' => 'Pred časťou s údajmi o zákazníkovi','After customer details section' => 'Po časti s údajmi o zákazníkovi','Account creation benefits' => 'Výhody vytvorenia účtu','Leaving the field empty will display the default text.' => 'Ak toto pole ponecháte prázdne, zobrazí sa predvolený text.','Inline buttons' => 'Tlačidlá v texte','Required fields' => 'Povinné polia','Enable gift message fields at checkout' => 'Aktivovať polia pre darčekový odkaz pri dokončovaní objednávky','Expanded gift message' => 'Rozšírený text darčekového odkazu','Display gift message field always expanded' => 'Pole na zadanie darčekového odkazu sa má vždy zobrazovať v rozbalenom stave','Gift message in order details' => 'Správa k darčeku v podrobnostiach objednávky','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'V tejto sekcii momentálne nie sú k dispozícii žiadne integrácie. Možnosti týkajúce sa jednotlivých doplnkov a šablón sa tu zobrazia až po ich aktivácii.','Phone fields' => 'Pole pre telefónne čísla','Field visibility' => 'Viditeľnosť na ihrisku','Field position' => 'Poloha na ihrisku','Phone country code & validation' => 'Predvoľba krajiny pre telefón a overenie','Country' => 'Krajina','Enable country on phone fields' => 'Aktivovať polia pre výber krajiny v telefóne','Filter countries for shipping or billing' => 'Filtrovať krajiny pre doručenie alebo fakturáciu','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Obmedzte výber krajiny v každom poli pre telefónne číslo len na krajiny, do ktorých je vo vašom obchode povolená expedícia alebo fakturácia.','Validation' => 'Overenie','Enable simple validation based on country rules' => 'Aktivovať jednoduchú validáciu na základe pravidiel pre jednotlivé krajiny','Checks that the phone number is valid for the selected country, including country code and length.' => 'Overí, či je telefónne číslo platné pre vybranú krajinu, vrátane predvoľby a počtu číslic.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Prísnejšia kontrola, či je číslo platným mobilným číslom, číslom pevnej linky alebo iným typom čísla akceptovaným pre vybranú krajinu. Môže dôjsť k odmietnutiu niektorých platných čísel.','Validation types' => 'Typy validácie','Placeholders' => 'Zástupné znaky','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'V súčasnosti nie sú k dispozícii žiadne licenčné kľúče, ktoré by bolo potrebné spravovať. Licenčné kľúče sa tu zobrazia, keď bude aktívny licencovaný doplnok alebo rozšírenie Fluid Checkout.','Default delivery type' => 'Predvolený spôsob doručenia','Choose which delivery type will be selected by default.' => 'Vyberte, ktorý typ doručenia sa má nastaviť ako predvolený.','Shipping zone fields' => 'Polia pre prepravné zóny','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Vyberte, ktoré polia sa majú zobraziť v rámci filtrov pre zónu doručenia „osobný odber“. Ak necháte polia prázdne, zobrazia sa všetky dostupné možnosti.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Tieto polia sa zobrazia ako filter pre spôsoby doručenia s osobným vyzdvihnutím. Niektoré polia sa môžu aj naďalej zobrazovať pri dokončovaní objednávky, ak tu nie sú vybrané, ak ich kompatibilné pluginy vyžadujú na správne fungovanie.','Order shipping address' => 'Adresa na doručenie objednávky','Order pay page optimization' => 'Optimalizácia stránky na zadávanie objednávok','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Neuhradeným objednávkam priraďte rovnaké prehľadné rozloženie zamerané na konverziu ako pri dokončovaní nákupu.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimalizujte rozloženie stránky platby pre objednávky, pri ktorých ešte nebola vykonaná platba.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Zosúlaďte proces platby s vašou pokladňou, aby bol nákupný proces jednotný.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Umístite symboly dôveryhodnosti a odznaky tam, kde zákazníci potrebujú uistenie pred uskutočnením platby.','Thank you page optimization' => 'Optimalizácia stránky s poďakovaním','Make the thank you page and order details clearer for customers after they buy.' => 'Zabezpečte, aby bola stránka s poďakovaním a podrobnosti o objednávke pre zákazníkov po nákupe prehľadnejšie.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimalizujte stránku s poďakovaním a podrobnosti o objednávke v účte pomocou prehľadnejšieho rozloženia.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Zobrazujte priebeh stavu objednávky, akcie, súbory na stiahnutie a poznámky tam, kde to dáva zmysel.','Customize order details sections on email notifications.' => 'Prispôsobte si časti s podrobnosťami objednávky v e-mailových oznámeniach.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Umístite symboly dôveryhodnosti a odznaky tam, kde zákazníci potrebujú uistenie po nákupe.','Email notifications' => 'E-mailové upozornenia','Enable thank you page and order details optimizations to see more options' => 'Aktivujte optimalizáciu stránky s poďakovaním a podrobností objednávky, aby ste videli viac možností','Use wide layout on thank you page' => 'Na stránke s poďakovaním použite široké rozloženie','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Tieto nastavenia ovplyvňujú stránku s poďakovaním, zobrazenie podrobností objednávky na stránkach účtu a v e-mailových oznámeniach.','Save settings' => 'Uložiť nastavenia','Docs' => 'Dokumenty','Cart' => 'Košík','Thank you' => 'Ďakujem','Address autocomplete' => 'Automatické dopĺňanie adries','Trust badges' => 'Odznaky dôveryhodnosti','You do not have permission to save these settings.' => 'Nemáte oprávnenie na uloženie týchto nastavení.','Invalid save request.' => 'Neplatná žiadosť o uloženie.','Your settings have been saved.' => 'Vaše nastavenia boli uložené.','Saving...' => 'Ukladá sa...','Settings could not be saved. Please try again.' => 'Nastavenia sa nepodarilo uložiť. Skúste to prosím znova.','Dismiss notice' => 'Zatvoriť upozornenie','Open settings menu' => 'Otvoriť ponuku nastavení','Close settings menu' => 'Zatvoriť ponuku nastavení','Preview' => 'Náhľad','Expand preview' => 'Rozbaliť náhľad','Collapse preview' => 'Zatvoriť náhľad','Show header and footer' => 'Zobraziť hlavičku a pätičku','Hide header and footer' => 'Skryť hlavičku a pätičku','Page preview' => 'Náhľad stránky','Preview viewport' => 'Náhľad zobrazenia','Tablet' => 'Tablet','Desktop' => 'Plocha','Preview width' => 'Šírka náhľadu','Decrease width' => 'Zmenšiť šírku','Preview width in pixels' => 'Šírka náhľadu v pixeloch','Increase width' => 'Zväčšiť šírku','Preview as' => 'Náhľad ako','Guest' => 'Hosť','Logged in' => 'Prihlásený','Preview page' => 'Náhľad stránky','Expand preview for a closer look' => 'Rozbaľte náhľad, aby ste si ho mohli prezrieť podrobnejšie','Available with %s.' => 'K dispozícii s %s.','Turn them on' => 'Zapnite ich','Optimizations for this page are turned off. %s to preview the page.' => 'Optimalizácie pre túto stránku sú vypnuté. %s pre náhľad stránky.','%s preview' => 'Náhľad %s','Isolated session · nothing is saved' => 'Izolovaná relácia · nič sa neukladá','Usage tracking' => 'Sledovanie používania','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Odosielajte správy o prostredí webovej stránky, ktoré neobsahujú citlivé údaje, aby ste pomohli službe Fluid Checkout zlepšiť kompatibilitu. Správy sa neodosielajú, pokiaľ túto funkciu neaktivujete v nižšie uvedených nastaveniach.','Send usage tracking reports to Fluid Checkout' => 'Odoslať správy o sledovaní využitia do služby Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Tieto správy nám pomáhajú zlepšovať kompatibilitu a podporu vašej stránky a v prípade, že je táto funkcia zapnutá, zasielajú sa každý týždeň.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Správy neobsahujú žiadne údaje o zákazníkoch, správcoch ani žiadne iné citlivé údaje.','Basic environment info' => 'Základné informácie o prostredí','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Údaje o WordPresse, PHP, WooCommerce, šablónach a zozname doplnkov. Vždy sa zahrnú, ak je povolené vytváranie správ. Pomáhajú nám pochopiť prostredie, v ktorom vaša stránka beží.','Plugin settings' => 'Nastavenia doplnku','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Odosiela nastavenia doplnku Fluid Checkout, čo pomáha pri vybavovaní žiadostí o podporu a umožňuje nám lepšie pochopiť, ako naše doplnky používate.','Coming soon' => 'Už čoskoro','Sales metrics' => 'Ukazovatele predaja','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Počet objednávok za mesiac a celkový obrat za obdobie jedného roka pred inštaláciou Fluid Checkout až po dnešok. Pomáha nám to zistiť, či s nainštalovanými našimi doplnkami dosahujete vyššie tržby. Nikdy sa neposielajú žiadne údaje o zákazníkoch ani používateľoch.','Utilities' => 'Služby','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Použite roletové komponenty <code>TomSelect</code> namiesto <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect je jednoduchšia komponenta s roletovým výberom, ktorá je menej náchylná na chyby ako Select2, pričom ponúka rovnakú funkčnosť.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Nastaví veľkosť písma vo formulárových poliach na 16px na stránkach optimalizovaných týmto doplnkom, aby sa zabránilo automatickému zväčšovaniu pri práci s formulárovými poliami na malých zariadeniach.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari a iné prehliadače môžu na mobilných zariadeniach automaticky zväčšiť zobrazenie, aby bol text čitateľnejší, ak je veľkosť písma menšia ako 16px.','Enable script processing tracking on the browser console.' => 'Zapnite sledovanie spracovania skriptov v konzole prehliadača.','Unminified assets' => 'Neminifikované súbory','Google Maps scripts' => 'Skripty pre Google Maps','Do not remove duplicate Google Maps scripts' => 'Neodstraňujte duplicitné skripty služby Google Maps','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Ak je táto možnosť zapnutá, duplicitné skripty služby Google Maps sa NEODSTRÁNIA, čo môže spôsobiť chyby a problémy s výkonom. Túto možnosť používajte iba pri riešení problémov.','Widget areas' => 'Oblasti pre widgety','Last step on mobile' => 'Posledný krok na mobilnom zariadení','Display widgets only at last step on mobile' => 'Na mobilných zariadeniach zobrazovať widgety až v poslednom kroku','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Zobrazovať widgety s označením dôveryhodnosti pri platbe iba pri zobrazení posledného kroku platby na mobilných zariadeniach','Standard' => 'Štandard','VAT number field' => 'Pole pre číslo DPH','Add a VAT number field to the billing form.' => 'Do fakturačného formulára pridajte pole pre DIČ.','Field label' => 'Názov poľa','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Nastavte názov poľa pre DIČ (napr. DIČ). Na viacjazyčných webových stránkach je lepšie nechať toto pole prázdne a preložiť pôvodný reťazec.','VAT Number' => 'DIČ','EU-VAT' => 'DPH v EÚ','Enable the VAT number field to see more options' => 'Aktivujte pole pre DIČ, aby sa zobrazili ďalšie možnosti','VAT validation' => 'Overenie DPH','Validate VAT number field for EU-VAT during checkout' => 'Overiť pole pre číslo DPH pre DPH v EÚ počas dokončenia objednávky','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Overí, či zadané DIČ je platné DIČ zaregistrované v európskej databáze VIES (Systém výmeny informácií o DPH).','Shop VAT number' => 'DIČ obchodu','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'DIČ obchodu, ktoré sa používa na žiadosť o overenie DIČ v EÚ a je uvedené na faktúrach. <br><strong>Dôrazne odporúčame uviesť DIČ vášho obchodu</strong>, pretože v opačnom prípade výsledky vyhľadávania v systéme VIES nemusia byť platné na účtovné účely. <br>Napr.: <code>ATU99999999</code> alebo <code>EE999999999</code>.','Reverse charge' => 'Mechanizmus presunu daňovej povinnosti','Apply reverse charge mechanism' => 'Uplatniť mechanizmus presunu daňovej povinnosti','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Nastavte daňovú sadzbu na nulu a na faktúrach zobrazujte text „Reverse charge“, ak je DIČ zákazníka platné. V závislosti od krajiny, v ktorej sa nachádza obchod, môže byť potrebný iný text pre „Reverse charge“.','Same country' => 'Tá istá krajina','Apply reverse charge mechanism for transactions in the shop country:' => 'Na transakcie v krajine, kde sa nachádza predajňa, uplatnite mechanizmus prenesenia daňovej povinnosti:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Umožňuje uplatňovanie mechanizmu presunu daňovej povinnosti pri transakciách medzi spoločnosťami v tej istej krajine, v ktorej sa nachádza obchod.','Reverse charge exceptions' => 'Výnimky z mechanizmu presunu daňovej povinnosti','Select additional countries to skip applying the reverse charge mechanism.' => 'Vyberte ďalšie krajiny, v ktorých sa nemá uplatňovať mechanizmus presunu daňovej povinnosti.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Pri objednávkach z týchto krajín budú účtované dane aj v prípade, že bude uvedené platné DIČ.','Reverse charge label on invoices' => 'Označenie o prenesení daňovej povinnosti na faktúrach','Set the label of "reverse charge" on the checkout page and order details.' => 'Na stránke pokladne a v podrobnostiach objednávky nastavte označenie „reverse charge“.','Reverse charge text on invoices' => 'Text o mechanizme prenesenia daňovej povinnosti na faktúrach','Set the label of "reverse charge" text on invoices.' => 'Nastavte označenie textu „reverse charge“ na faktúrach.','Tax to be paid on reverse charge basis' => 'Daň, ktorá sa má zaplatiť na základe mechanizmu presunutia daňovej povinnosti','Company name' => 'Názov spoločnosti','Autocomplete company name from VAT number' => 'Automatické dopĺňanie názvu spoločnosti na základe DIČ','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Vyplňte názov fakturačnej spoločnosti na základe platného DIČ, ktoré poskytol zákazník.','Company name editing' => 'Úprava názvu spoločnosti','Allow editing of auto-filled company name' => 'Povoliť úpravu automaticky vyplneného názvu spoločnosti','When enabled, customers can change the company name associated with the provided VAT number.' => 'Ak je táto funkcia povolená, zákazníci môžu zmeniť názov spoločnosti priradený k zadanému číslu DPH.','EU-VAT for digital goods' => 'DPH EÚ pre digitálny tovar','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Od 1. januára 2015 nadobudli účinnosť zmeny v predpisoch EÚ o DPH týkajúcich sa digitálneho tovaru, ktoré sa týkajú výlučne transakcií typu B2C. DPH z digitálneho tovaru sa musí vypočítať na základe miesta pobytu zákazníka a je potrebné zhromaždiť príslušné dôkazy (IP adresa a fakturačná adresa).','Tax classes for digital goods' => 'Daňové triedy pre digitálny tovar','Select some tax classes' => 'Vyberte niektoré daňové triedy','Location evidence' => 'Dôkazy o mieste','Collect customer\'s location evidence' => 'Získajte dôkazy o polohe zákazníka','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Uloží IP adresu a overí jej zhodu s fakturačnou adresou zákazníka. Ak sa krajina uvedená vo fakturačnej adrese nezhoduje s krajinou IP adresy, zákazník musí potvrdiť svoju fakturačnú adresu zaškrtnutím políčka na stránke dokončenia objednávky.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Táto možnosť sa nastavuje v nástroji Fluid Checkout. <a href="%s">Zmeňte ju v nastaveniach zákazníckych účtov</a>.','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Túto možnosť spravujete v module Fluid Checkout. Zmeniť ju môžete v časti Fluid Checkout > Zákaznícke účty.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Táto možnosť sa nastavuje v Fluid Checkout. Ak je Fluid Checkout aktivovaný, miesto doručenia je vždy nastavené na „Predvolene na doručovaciu adresu zákazníka“. Zákazníci môžu aj naďalej uvádzať odlišné dodacie a fakturačné adresy počas dokončovania objednávky.<br><br>Možnosť nastaviť predvolenú fakturačnú adresu tak, aby bola zhodná s dodacou adresou, je k dispozícii v <a href="%s">nastaveniach Fluid Checkout</a>.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Táto možnosť sa nastavuje v module Fluid Checkout. Ak je Fluid Checkout aktivovaný, miesto doručenia je vždy nastavené na „Predvolene na doručovaciu adresu zákazníka“. Zákazníci môžu aj naďalej uvádzať odlišné doručovacie a fakturačné adresy počas dokončovania objednávky.<br><br>Možnosť nastaviť predvolenú fakturačnú adresu tak, aby bola zhodná s doručovacíou adresou, je k dispozícii v sekcii WooCommerce > Nastavenia > Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Tieto nastavenia boli presunuté do sekcie WP Admin > Fluid Checkout > Nastavenia.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Táto karta „Nastavenia WooCommerce“ je zastaraná a vo verzii Fluid Checkout 6.0 bude odstránená.','Go to settings page' => 'Prejsť na stránku nastavení','Hide this tab permanently' => 'Trvalo skryť túto kartu','Site report preview' => 'Náhľad správy o lokalite','This is the data that would be included in the next site environment report based on your current settings.' => 'Toto sú údaje, ktoré by boli zahrnuté v nasledujúcej správe o prostredí lokality na základe vašich aktuálnych nastavení.','Loading report preview...' => 'Načítava sa náhľad správy...','Could not load the site report preview. Try again.' => 'Nepodarilo sa načítať náhľad správy o webe. Skúste to znova.','Could not send the site report. Try again.' => 'Nepodarilo sa odoslať správu o stránke. Skúste to znova.','Site report sent successfully.' => 'Správa o lokalite bola úspešne odoslaná.','Enable and send now' => 'Aktivovať a odoslať teraz','Close' => 'Zatvoriť','A site report request is already in progress. Try again in a moment.' => 'Žiadosť o správu o stavenisku sa už spracováva. Skúste to o chvíľu znova.','Site environment reporting is disabled.' => 'Vytváranie správ o prostredí lokality je deaktivované.','No site report data is available to send.' => 'Nie sú k dispozícii žiadne údaje zo správ o lokalitách, ktoré by bolo možné odoslať.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Táto doména nemôže odosielať správy o prostredí (s výnimkou lokálnych alebo vývojových domén).','A site report was sent recently. Try again later.' => 'Nedávno bola odoslaná správa o lokalite. Skúste to neskôr.','The site report could not be sent. Try again later.' => 'Správa o lokalite sa nepodarilo odoslať. Skúste to neskôr.','Site environment reporting is not available.' => 'Správa o stave lokality nie je k dispozícii.','No site report data is available for the selected settings.' => 'Pre vybrané nastavenia nie sú k dispozícii žiadne údaje zo správ o lokalitách.','You are not allowed to manage site reports.' => 'Nemáte oprávnenie spravovať správy o webe.','PRO feature' => 'Funkcia PRO','Other plugins' => 'Ďalšie doplnky','Get only this add-on &mdash; %s' => 'Kúpte si len tento doplnok — %s','Install add-on' => 'Nainštalovať doplnok','Upgrade to PRO &mdash; %s' => 'Prechod na verziu PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Získajte %2$s</a>, aby ste odomkli tieto možnosti.','Add-on' => 'Doplnok','View documentation' => 'Zobraziť dokumentáciu','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Žiadosti vyžadujú prihláseného používateľa WordPressu. Ak chcete použiť údaje aktuálneho používateľa, vynechajte parameter user_id, alebo zadajte hodnotu user_id, ak chcete osloviť iný účet, ak má volajúci oprávnenie na úpravu daného používateľa (oprávnenie edit_user). Neautentifikované žiadosti vracajú chybu fc_api_forbidden. Neplatné user_id vráti fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 s { "data": { ... } }, keď obslužná funkcia vráti dátovú časť.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 s { "success": true }, ak nie je prítomný dátový obsah (napríklad pri DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Pri chybách sa vráti JSON s chybou WordPress REST z triedy WP_Error (kód, správa, data.status). Kódy v rozhraní používajú predponu fc_api_*.','Forbidden access.' => 'Prístup zakázaný.','Target user was not found.' => 'Cieľový používateľ nebol nájdený.','This feature is not available.' => 'Táto funkcia nie je k dispozícii.','A required address field is missing.' => 'Chýba povinné pole pre zadanie adresy.','Postcode or ZIP is invalid.' => 'PSČ alebo ZIP kód je neplatný.','Phone number is invalid.' => 'Telefónne číslo je neplatné.','State or county is invalid.' => 'Štát alebo okres je neplatný.','Country is invalid or has no address fields.' => 'Krajina je neplatná alebo neobsahuje žiadne polia pre adresu.','The request could not be processed.' => 'Žiadosť sa nepodarilo spracovať.','Back to previous step' => 'Späť na predchádzajúci krok','Skip to settings' => 'Prejsť na nastavenia','Start over and return to the first guided setup step' => 'Začnite od začiatku a vráťte sa k prvému kroku sprievodcu nastavením','Start over' => 'Začať od začiatku','Please complete all sub-steps before continuing.' => 'Pred pokračovaním prosím vykonajte všetky čiastkové kroky.','Expand' => 'Rozbaliť','Collapse' => 'Zatvoriť','Skip' => 'Preskočiť','Mark as complete' => 'Označiť za dokončené','Mark as incomplete' => 'Označiť ako neúplné','View full-size image: %s' => 'Zobraziť obrázok v plnej veľkosti: %s','Full-size setup guide image' => 'Obrázok s návodom na nastavenie v plnej veľkosti','Close image' => 'Zatvoriť obrázok','Fluid Checkout Guided Setup' => 'Návod na nastavenie systému Fluid Checkout','Welcome' => 'Vitajte','Explore your checkout' => 'Prezrite si svoj nákupný košík','All set' => 'Všetko je pripravené','You do not have permission to access this page.' => 'Nemáte oprávnenie na prístup k tejto stránke.','Go to step %1$d: %2$s' => 'Prejsť na krok %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Toto nastavenie s návodom vám pomôže zoznámiť sa so službou Fluid Checkout. Nižšie uvedené kroky sú zatiaľ len náhradné texty.','Continue to the next step when you are ready.' => 'Až budete pripravení, pokračujte ďalším krokom.','Open your store checkout to see Fluid Checkout in action.' => 'Otvorte pokladňu svojho obchodu a pozrite si, ako funguje Fluid Checkout.','View checkout page' => 'Zobraziť stránku platby','You can return to Fluid Checkout settings to continue configuring your store.' => 'Môžete sa vrátiť do nastavení Fluid Checkout a pokračovať v konfigurácii vášho obchodu.','Review checkout and cart settings' => 'Skontrolujte nastavenia pokladne a nákupného košíka','Explore add-ons from the dashboard' => 'Prezrite si doplnky na riadiacom paneli','Finish & go to settings' => 'Dokončiť a prejsť do nastavení','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Zmeňte nastavenie viditeľnosti poľa „telefón na fakturačné účely“ zo pôvodnej hodnoty tak, aby zodpovedalo konvenciám WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Zmeňte nastavenie viditeľnosti poľa „Telefón pre doručenie“ zo pôvodnej hodnoty tak, aby zodpovedalo konvenciám WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Skopírujte nastavenie farby pozadia súhrnu objednávky do novej možnosti farby pozadia sekundárneho stĺpca v dizajne „Split“.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Pri používaní doplnku Biteship je funkcia rozšírených výberových polí vždy deaktivovaná.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Pri používaní pluginu German Market je poloha tlačidla na zadanie objednávky vždy nastavená na „Pod súhrnom objednávky“. Tento plugin vyžaduje, aby sa tlačidlo na zadanie objednávky a zaškrtávacie políčka s právnymi informáciami zobrazovali pod súhrnom objednávky.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Pri používaní doplnku Germanized for WooCommerce je poloha tlačidla na odoslanie objednávky vždy nastavená na „Pod súhrnom objednávky“. Tento doplnok vyžaduje, aby sa tlačidlo na odoslanie objednávky a zaškrtávacie políčka s právnymi informáciami zobrazovali pod súhrnom objednávky.','Edit pickup locations' => 'Upraviť miesta vyzdvihnutia','Use local pickup label from WooCommerce settings' => 'Použiť štítok na osobný odber z nastavení WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Ak je táto funkcia zapnutá, názov možnosti osobného vyzdvihnutia pri platbe zodpovedá názvu z nastavení miesta osobného vyzdvihnutia v WooCommerce. Ak je táto funkcia vypnutá, názov používa preložiteľný text „Osobné vyzdvihnutie“ z modulu Fluid Checkout.','Button label for applying coupon codesApply' => 'Aplikovať','Checkout step titleContact' => 'Kontakt','Checkout step titleShipping' => 'Preprava','Checkout step titleBilling' => 'Fakturácia','Checkout step titlePayment' => 'Platba','Checkout substep change link labelChange' => 'Zmena','Checkout substep save link labelSave changes' => 'Uloženie zmien','Substep review textNone.' => 'Žiadne.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Nie je vybratý žiadny obrázok.','Settings sectionCart' => 'Košík','Settings sectionOrder pay' => 'Objednávka platby','Settings sectionThank you' => 'Ďakujem','Settings section titleIntegrations' => 'Integrácie','Settings section titleLicense keys' => 'Licenčné kľúče','Captcha positionBefore place order section' => 'Pred umiestnením objednávky','Captcha positionBefore place order button' => 'Pred tlačidlom umiestniť objednávku','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Zatvoriť','Log in link label at checkout contact stepLog in' => 'Prihlásiť sa','Log in separator label at for when guest checkout is disabledOr continue below' => 'Alebo pokračujte nižšie','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Alebo pokračujte ako hosť','Clear image selection on admin pages.Remove image' => 'Odstrániť obrázok','shipping packagesShipping %d' => 'Preprava %d','shipping packagesShipping' => 'Preprava','Used as fallback for "Proceed to next step" button labelnext step' => 'ďalší krok','Substep review checkbox valueYes' => 'Áno','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'John','Dummy customer last name in the admin previewDoe' => 'Lanička','Dummy customer company in the admin previewExample Company' => 'Príklad spoločnosti','Dummy customer street address in the admin preview123 Main Street' => '123 Hlavná ulica','Dummy customer city in the admin previewAnytown' => 'Akékoľvek mesto','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Balík prosím odložte pri vchodových dverách.','Dummy product name in the admin previewBeanie' => 'Čiapka','Dummy product name in the admin previewCap' => 'Čiapka','Dummy product name in the admin previewT-Shirt' => 'Tričko','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Vašu objednávku sme prijali a po jej odoslaní vám pošleme informáciu o stave zásielky.','Dummy download in the admin previewUser guide' => 'Návod na použitie','Google Places API versionsPlaces API (New)' => 'Rozhranie Places API (nové)','Google Places API versionsPlaces API (Legacy)' => 'Rozhranie API miest (staršia verzia)','Brasil API versionsVersion 1' => 'Verzia 1','Brasil API versionsVersion 2' => 'Verzia 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
